// Validate the incoming email. Throwing an error sends the item down the error branch.
const email = $('Webhook: new enquiry').first().json.body || {};
if (!String(email.body || '').trim()) throw new Error('missing email body');
if (!String(email.from_email || '').includes('@')) throw new Error('missing or invalid from_email');

// Deterministic tripwire for prompt injection (same patterns as the Python reference).
const INJECTION_PATTERNS = ["ignore (all |the )?(previous|prior|above)? ?(instructions|rules)", "ignore the rules", "system (note|prompt)", "admin mode", "تجاهل (جميع |كل )?(التعليمات|القواعد)", "ignorez (les|toutes les) instructions"];
const text = `${email.subject || ''}\n${email.body}`;
const runTag = email.run_tag || '';
const keySource = email.message_id || `${email.from_email}|${email.subject || ''}|${email.body}`;
return [{
  json: {
    message_id: String(email.message_id || 'unknown'),
    email,
    injection_suspected: INJECTION_PATTERNS.some((pattern) => new RegExp(pattern, 'i').test(text)),
    dedupe_text: `${runTag}|${keySource}`,
  },
}];

// Idempotency: the same input twice must not create two records.
// Keys live in this workflow's static data (n8n saves it after production runs, not manual test runs).
const item = $input.first().json;
const key = item.dedupe_key || item.dedupe_text;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = Boolean(store.seen[key]);
if (!duplicate) store.seen[key] = new Date().toISOString();
const json = { ...item, dedupe_key: key, is_duplicate: duplicate };
const binary = undefined; // invoices carry the uploaded file along
return [binary ? { json, binary } : { json }];

