    ...item,
    step: 'ai_classify',
    llm_request: {
      model: cfg.model_cheap,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: cfg.prompt_classify }, { role: 'user', content: user }],
    },
  },
}];

// JSON-schema check of the model's reply. Invalid output is never used: it goes to human review.
// Parse the model's reply and check it against a JSON Schema (the subset our schemas use).
function parseJsonObject(text) {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}
function isType(value, type) {
  if (type === 'null') return value === null;
  if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (type === 'integer') return Number.isInteger(value);
  if (type === 'object') return value !== null && typeof value === 'object' && !Array.isArray(value);
  if (type === 'array') return Array.isArray(value);
  return typeof value === type;
}
function schemaErrors(value, schema, path = '$') {
  if (value === null && path === '$') return ['output is not a JSON object'];
  const types = [].concat(schema.type || []);
  if (types.length && !types.some((type) => isType(value, type))) return [`${path}: expected ${types.join(' or ')}`];
  const errors = [];
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${path}: must be one of ${JSON.stringify(schema.enum)}`);
  if (typeof value === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: below ${schema.minimum}`);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${path}: above ${schema.maximum}`);
  }
  if (typeof value === 'string') {
    if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${path}: longer than ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errors.push(`${path}: does not match ${schema.pattern}`);
  }
  if (isType(value, 'object')) {
    const properties = schema.properties || {};
    for (const key of schema.required || []) if (!(key in value)) errors.push(`${path}.${key}: missing`);
    for (const [key, sub] of Object.entries(properties)) if (key in value) errors.push(...schemaErrors(value[key], sub, `${path}.${key}`));
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) if (!(key in properties)) errors.push(`${path}.${key}: not allowed`);
    }
  }
  return errors;
}
const SCHEMA = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Enquiry classification and fields", "type": "object", "required": ["category", "name", "company", "need", "urgency", "language", "confidence"], "additionalProperties": false, "properties": {"category": {"type": "string", "enum": ["sales", "support", "complaint", "partnership", "spam"]}, "name": {"type": ["string", "null"], "maxLength": 120}, "company": {"type": ["string", "null"], "maxLength": 160}, "need": {"type": "string", "maxLength": 300}, "urgency": {"type": "string", "enum": ["low", "medium", "high"]}, "language": {"type": "string", "enum": ["en", "ar", "fr", "mixed"]}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}}};
const { llm_request, ...context } = $('Build AI request').first().json;
const content = $input.first().json.choices?.[0]?.message?.content || '';
const ai = parseJsonObject(content);
const errors = schemaErrors(ai, SCHEMA);
return [{ json: { ...context, ai: errors.length ? null : ai, schema_errors: errors } }];

// Business rules in code: the AI only labels the email, code decides what happens next.
const TEAM_BY_CATEGORY = {"sales": "Sales", "support": "Customer Support", "complaint": "Customer Care", "partnership": "Partnerships", "spam": "Spam archive"};
const cfg = $('Config').first().json;
const item = $input.first().json;
const ai = item.ai;

function route(ai, injection, threshold) {
  if (ai === null) return { status: 'needs_review', reason: 'AI output failed the JSON schema check', team: 'Review queue' };
  const team = TEAM_BY_CATEGORY[ai.category];
  const flag = ai.category === 'complaint' && ai.urgency === 'high' ? 'manager_cc' : '';
  if (injection) return { status: 'needs_review', reason: 'possible prompt injection', team, flag };
  if (ai.category === 'spam') return { status: 'archived_spam', reason: 'spam: no reply drafted', team, flag };
  if (ai.confidence < threshold) return { status: 'needs_review', reason: 'low confidence', team, flag };
  return { status: 'to_draft', reason: '', team, flag };
}

return [{ json: { ...item, ...(ai || {}), ...route(ai, item.injection_suspected, Number(cfg.confidence_threshold)) } }];

// Second AI call: draft a reply. It is only a draft; a person approves it before anything is sent.
