const COLUMNS = ["timestamp", "workflow", "item_id", "step", "error_type", "message"];
const cfg = $('Config').first().json;
const item = $input.first().json;
const error = item.error || 'unknown error';
const message = typeof error === 'string' ? error : error.description || error.message || JSON.stringify(error);
let itemId = 'unknown';
try {
  itemId = $('Webhook: new enquiry').first().json.body.message_id || itemId; // straight from the trigger, in case the input check failed
